#include <bits/stdc++.h>
using namespace std;

const int MD = 998244353;

long long power(long long a, long long k) {
    if (k == 0) return 1;
    long long p = power(a, k >> 1);
    p = p * p % MD;
    if (k & 1) p = p * a % MD;
    return p;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long k_;
    cin >> n >> k_;

    if (k_ >= n) {
        cout << 0 << '\n';
        return 0;
    }

    int c = n - (int)k_;

    vector<int> ff(2 * n);
    vector<int> gg(2 * n);

    long long f = 1;
    for (int i = 0; i < 2 * n; ++i) {
        ff[i] = (int)f;
        gg[i] = (int)power(f, MD - 2);
        f = f * (i + 1) % MD;
    }

    auto ch = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return (long long)ff[n] * gg[k] % MD * gg[n - k] % MD;
    };

    long long ans = 0;
    for (int a = 1; a <= c; ++a) {
        long long x = power(a, n) * ch(c, a) % MD;
        if ((c - a) % 2 == 0)
            ans += x;
        else
            ans -= x;
    }

    ans %= MD;
    if (ans < 0) ans += MD;

    ans = ans * ch(n, c) % MD;

    if (k_ > 0)
        ans = ans * 2 % MD;

    cout << ans << '\n';

    return 0;
}

